param()
$ErrorActionPreference='Stop'; $root=(Get-Location).Path; if(-not (Test-Path -LiteralPath (Join-Path $root '.git'))){throw 'Repository root에서 실행하세요.'}; $expected='4870b20733875c3955f93846307fa5041e6f6c22'; $head=(git rev-parse HEAD).Trim(); if($head -ne $expected){throw "HEAD mismatch. expected=$expected actual=$head"}; $m=Join-Path $root 'cpf-docs/work/v9i/final-control/PROJECT_CONTROL_DELETE_MANIFEST.csv'; $dm=Join-Path $root 'cpf-docs/work/v9i/final-control/PROJECT_CONTROL_EMPTY_DIR_MANIFEST.csv'; $protected=@('README.md','cpf-docs/guides/','cpf-docs/deliverables/','cpf-docs/assets/manuals/','cpf-docs/assets/readme/','cpf-docs/specification/CPF_DOCUMENTATION_STANDARD.md','cpf-docs/environment/docker/','cpf-tools/environment/docker-development-test/','cpf-docs/governance/','cpf-docs/work/v9i/final-control/','cpf-docs/work/v9i/final-dev-request/','cpf-docs/work/v9i/qa/final-a/','cpf-docs/work/v9i/qa/final-b/','cpf-docs/work/v9i/dev-r6j14/','cpf-docs/work/v9i/qa/r6j/','cpf-docs/work/v9i/results/'); Import-Csv -LiteralPath $m | ForEach-Object { $rel=($_.path -replace '\\','/'); if([string]::IsNullOrWhiteSpace($rel) -or [IO.Path]::IsPathRooted($rel) -or $rel.Contains('*') -or $rel.Contains('?') -or $rel.Split('/') -contains '..'){throw "Unsafe delete path: $rel"}; foreach($pp in $protected){if($rel -eq $pp.TrimEnd('/') -or $rel.StartsWith($pp,[StringComparison]::OrdinalIgnoreCase)){throw "Protected path blocked: $rel"}}; $dirty=@(git status --porcelain --untracked-files=no -- $rel); if($dirty.Count -gt 0){throw "Delete target has uncommitted change: $rel"}; $p=Join-Path $root $rel; if(Test-Path -LiteralPath $p -PathType Leaf){Remove-Item -LiteralPath $p -Force} elseif(Test-Path -LiteralPath $p){throw "Manifest path is not a file: $rel"} }; Import-Csv -LiteralPath $dm | ForEach-Object { $rel=($_.path -replace '\\','/'); if([IO.Path]::IsPathRooted($rel) -or $rel.Contains('*') -or $rel.Contains('?') -or $rel.Split('/') -contains '..'){throw "Unsafe directory path: $rel"}; $p=Join-Path $root $rel; if(Test-Path -LiteralPath $p -PathType Container){$children=@(Get-ChildItem -LiteralPath $p -Force); if($children.Count -eq 0){Remove-Item -LiteralPath $p -Force}else{Write-Host "KEEP(non-empty): $rel"}} }; git status --short
